root = ET.fromstring(xml)
ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}
parent_map = {c: p for p in root.iter() for c in p}
for t in root.iter('{http://www.hancom.co.kr/hwpml/2010/HWPML}t'):
    node = t
    while node is not None and node.tag != '{http://www.hancom.co.kr/hwpml/2010/HWPML}p':
        print('current tag:', node.tag)
        node = parent_map.get(node)
    print('found p?', node is not None)
"

