import zipfile

# Check it's a valid ZIP
with zipfile.ZipFile('/root/inventory_report_ready.hwpx', 'r') as z:
    bad = z.testzip()
    if bad:
        print('BAD ZIP, first bad file:', bad)
    else:
        print('Valid ZIP')

    # Check no placeholders remain
    for info in z.infolist():
        if info.filename.lower().endswith('.xml'):
            content = z.read(info.filename).decode('utf-8')
            if '{{' in content:
                print('BAD: placeholders remain in', info.filename)
            else:
                print('No placeholders in', info.filename)

    # Verify Korean text preserved
    content = z.read('Contents/section0.xml').decode('utf-8')
    for label in ['재고 현황 보고서', '주요 품목:', '비고: 월간 정기 보고']:
        if label in content:
            print('Korean preserved:', label)
        else:
            print('MISSING Korean:', label)

    # Check empty paragraphs preserved
    empty_count = content.count('<hp:t />')
    print('Empty paragraphs count:', empty_count)
"

